using System.Collections.Generic;
using UnityEngine;

namespace LAB2D.AgentGenerated
{
    /// <summary>
    /// 可通过位掩码组合的输入锁定类型。
    /// 例如：Zoom（缩放）、Movement（移动）、CameraRotate（视角旋转）等。
    /// 可根据项目需要扩展。
    /// </summary>
    [System.Flags]
    public enum InputLocks
    {
        None = 0,
        /// <summary> 相机缩放（例如鼠标滚轮） </summary>
        Zoom = 1 << 0,
        // 预留扩展：Movement = 1 << 1, CameraRotate = 1 << 2, ...
    }

    /// <summary>
    /// 全局输入锁定管理器。
    /// 允许 UI 面板或其他系统请求临时禁用特定的游戏输入，
    /// 防止 UI 交互时误触底层玩法操作（如打开存档列表时鼠标滚轮导致相机缩放）。
    /// 
    /// 使用方法：
    /// 1. 在 UI 面板打开时调用 InputLockManager.Lock("SavePanel", InputLocks.Zoom)；
    /// 2. 在输入处理脚本中（如 CameraMove）调用 InputLockManager.IsLocked(InputLocks.Zoom)；
    /// 3. 面板关闭时调用 InputLockManager.Unlock("SavePanel", InputLocks.Zoom)。
    /// 
    /// 该组件可挂载到场景中的任意持久对象，
    /// 方便在 Inspector 中查看当前所有锁定原因与状态。
    /// </summary>
    public class InputLockManager : MonoBehaviour
    {
        /// <summary> 单例引用，便于外部调用静态方法的同时访问实例状态 </summary>
        public static InputLockManager Instance { get; private set; }

        // 记录每个锁定源（reason）当前锁定的输入类型
        private static readonly Dictionary<string, InputLocks> LockReasons = new Dictionary<string, InputLocks>();

        /// <summary> 当前所有锁定源生效的累积输入锁定标志（OR 运算结果） </summary>
        public static InputLocks CurrentLockFlags { get; private set; } = InputLocks.None;

        /// <summary>
        /// 请求锁定某类输入。
        /// 如果同一个 reason 多次 Lock，会覆盖上一次该 reason 的锁定标志。
        /// </summary>
        /// <param name="reason">锁定来源标识，例如 "SavePanel"</param>
        /// <param name="flags">要锁定的输入类型组合</param>
        public static void Lock(string reason, InputLocks flags)
        {
            if (string.IsNullOrEmpty(reason))
            {
                Debug.LogError("InputLockManager.Lock: reason 不能为空。");
                return;
            }

            LockReasons[reason] = flags;
            RecalculateCurrentFlags();
        }

        /// <summary>
        /// 解除某个锁定源的所有锁定。
        /// </summary>
        /// <param name="reason">之前 Lock 时使用的 reason</param>
        public static void Unlock(string reason, InputLocks flags)
        {
            if (string.IsNullOrEmpty(reason))
            {
                Debug.LogError("InputLockManager.Unlock: reason 不能为空。");
                return;
            }

            if (LockReasons.TryGetValue(reason, out InputLocks currentFlags))
            {
                // 移除该 reason 锁定的对应标志
                currentFlags &= ~flags;
                if (currentFlags == InputLocks.None)
                {
                    LockReasons.Remove(reason);
                }
                else
                {
                    LockReasons[reason] = currentFlags;
                }
                RecalculateCurrentFlags();
            }
        }

        /// <summary>
        /// 完全移除某个 reason 的所有锁定。
        /// </summary>
        /// <param name="reason">锁定来源</param>
        public static void UnlockAll(string reason)
        {
            if (string.IsNullOrEmpty(reason))
            {
                Debug.LogError("InputLockManager.UnlockAll: reason 不能为空。");
                return;
            }

            if (LockReasons.Remove(reason))
            {
                RecalculateCurrentFlags();
            }
        }

        /// <summary>
        /// 检查指定的输入类型当前是否被任意锁定源锁定。
        /// </summary>
        /// <param name="flag">要检查的输入类型</param>
        /// <returns>如果锁定返回 true</returns>
        public static bool IsLocked(InputLocks flag)
        {
            return (CurrentLockFlags & flag) != 0;
        }

        /// <summary>
        /// 获取当前所有 active 的锁定原因（用于调试显示）。
        /// </summary>
        public Dictionary<string, InputLocks> GetActiveLocks()
        {
            return new Dictionary<string, InputLocks>(LockReasons);
        }

        private static void RecalculateCurrentFlags()
        {
            InputLocks result = InputLocks.None;
            foreach (InputLocks flags in LockReasons.Values)
            {
                result |= flags;
            }
            CurrentLockFlags = result;
        }

        #region MonoBehaviour 单例与调试

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        private void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // 可在 Inspector 中查看的当前锁定状态
        [Header("调试信息 - 运行时只读")]
        [SerializeField] private string debugActiveReasons = "";
        [SerializeField] private InputLocks debugCurrentFlags = InputLocks.None;

        private void Update()
        {
            // 将动态状态同步到序列化字段以便在 Inspector 中查看
            debugCurrentFlags = CurrentLockFlags;
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            foreach (var kvp in LockReasons)
            {
                sb.AppendLine($"{kvp.Key}: {kvp.Value}");
            }
            debugActiveReasons = sb.ToString();
        }

        #endregion
    }
}
